 private final Screen parent;private final RequestSession session=new RequestSession();private JsonArray places=new JsonArray();private boolean loaded,busy,retry;private String cursor="",next="",notice="";
 PlacesScreen(Screen parent){super(Client.tr("ui.public_locations_c368f520"));this.parent=parent;}
 private int w(){return Math.min(470,width-40);}private int x(){return (width-w())/2;}private int top(){return UiDialog.top(height,360);}private int bottom(){return height-top();}
 private void request(String op,JsonObject body){if(busy)return;body.addProperty("action","community");body.addProperty("section","home");body.addProperty("op",op);busy=true;retry=false;ServerMenuClient.request(session.begin(body,!op.equals("toolsPlaces"),System.currentTimeMillis()));rebuildWidgets();}
