 @Override public void render(GuiGraphics g,int mx,int my,float d){UiDialog.render(parent,this,g,d,()->{super.render(g,mx,my,d);UiHeading.dialog(g,font,title,x(),top(),w());for(int n=firstRow;n<Math.min(places.size(),firstRow+visibleRows);n++){var row=places.get(n).getAsJsonObject();int y=top()+64+(n-firstRow)*72;String status=switch(Json.opt(row,"status","open")){case "closed"->Client.text("ui.closed_fc98a6f2");case "unavailable"->Client.text("ui.unavailable_949ac1f2");default->Client.text("ui.available_f925cafd");};Ui.text(g,font,font.plainSubstrByWidth(Json.str(row,"title")+" · "+status,w()-16),x()+6,y+6,UiPalette.color(0xD7E2EC));Ui.text(g,font,font.plainSubstrByWidth(Client.text("ui.author_d8cfdbaf")+Json.str(row,"author"),w()-44),x()+6,y+52,UiPalette.color(0xBAC7D2));}Ui.status(g,font,notice,x(),bottom()-78,w(),bottom()-56);});}
